'use strict';
let towerRange=7,towerPlayback=!matchMedia('(prefers-reduced-motion:reduce)').matches,towerEventIndex=0;
const towerHistory=[7,9,8,12,10,14,11,15,13,18,16,21,19,24];
const towerExamples=[
 ['RDS-26-03109','truck','Pickup confirmation received','Confirmación de recolección recibida','blue'],
 ['RDS-26-02833','box','Empty-return reminder prepared','Recordatorio de devolución preparado','amber'],
 ['RDS-26-03116','plane','Arrival forecast received','Pronóstico de llegada recibido','blue'],
 ['RDS-26-02554','file','Delivery order queued for review','Orden de entrega en cola de revisión','green'],
 ['RDS-26-03102','ship','Ocean milestone received','Hito marítimo recibido','blue'],
 ['RDS-26-03039','chat','Carrier follow-up drafted','Seguimiento al transportista redactado','purple'],
 ['RDS-26-03113','check','Delivery appointment confirmed','Cita de entrega confirmada','green'],
 ['RDS-26-02648','clock','Terminal cutoff flagged for review','Límite de terminal señalado para revisión','amber']
];
const towerBaseShell=workspaceShell;
workspaceShell=function(){return towerBaseShell().replace('shell studio ',`shell studio ${view==='overview'?'tower-workspace ':''}`)};
const towerBaseOverview=dashboardOverview;
dashboardOverview=function(){const original=towerBaseOverview();return workspacePrefs.widgets.analytics===false?original:original.replace('<div class="bento-grid">',`${towerAnalytics()}<div class="bento-grid">`)};
function towerAnalytics(){return`<div class="tower-analytics"><section class="tower-card tower-throughput" aria-labelledby="tower-trend-title"><header><div><span class="tower-kicker">${tr('OPERATIONAL MOMENTUM','RITMO OPERATIVO')}</span><h2 id="tower-trend-title">${tr('Shipment completions','Embarques completados')}</h2></div><div class="tower-range" role="group" aria-label="${tr('Chart period','Periodo del gráfico')}">${[7,14].map(n=>`<button data-tower-range="${n}" aria-pressed="${towerRange===n}">${n}${tr('d','d')}</button>`).join('')}</div></header><div id="tower-trend">${towerTrend()}</div><div class="tower-stage-strip">${towerStages()}</div></section><section class="tower-card tower-activity" aria-labelledby="tower-activity-title"><header><div><span class="tower-kicker">${tr('WORKSPACE ACTIVITY','ACTIVIDAD DEL ESPACIO')}</span><h2 id="tower-activity-title">${tr('Operations in motion','Operaciones en movimiento')}</h2></div><button class="tower-play ${towerPlayback?'playing':''}" data-tower-play aria-pressed="${towerPlayback}" aria-label="${towerPlayback?tr('Pause demo activity','Pausar actividad demo'):tr('Play demo activity','Reproducir actividad demo')}">${icon(towerPlayback?'pause':'play')}</button></header><div class="tower-feed-label"><i class="dot ${towerPlayback?'green':''}"></i><span>${tr('Simulated activity','Actividad simulada')}</span><span id="tower-play-status">${towerPlayback?tr('Playing','Reproduciendo'):tr('Preview','Vista previa')}</span></div><div id="tower-feed">${towerFeed()}</div><footer>${tr('Sample event playback · Shipment records stay in their current state.','Eventos de ejemplo · Los embarques conservan su estado actual.')}</footer></section><section class="tower-card tower-arrivals" aria-labelledby="tower-arrivals-title"><header><div><span class="tower-kicker">${tr('LOOKING AHEAD','PRÓXIMOS DÍAS')}</span><h2 id="tower-arrivals-title">${tr('Expected arrivals','Llegadas previstas')}</h2></div><span class="tower-chip">19–25 ${tr('Oct','oct')}</span></header>${towerArrivals()}</section><section class="tower-card tower-owners" aria-labelledby="tower-owners-title"><header><div><span class="tower-kicker">${tr('TEAM CAPACITY','CARGA DEL EQUIPO')}</span><h2 id="tower-owners-title">${tr('Active work by owner','Embarques activos por responsable')}</h2></div>${icon('users')}</header>${towerOwners()}</section></div>`}
function towerTrend(){
 const values=towerHistory.slice(-towerRange),total=values.reduce((a,b)=>a+b,0),max=30,W=600,H=132;
 const points=values.map((v,i)=>[34+i*(W-48)/(values.length-1),H-v/max*(H-12)]),line=points.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' '),area=`${line} L${points.at(-1)[0]},${H} L34,${H} Z`;
 const days=values.map((_,i)=>20-values.length+i);
 return`<div class="tower-trend-total"><strong>${total}</strong><span>${tr('completed in','completados en')} ${towerRange} ${tr('days','días')}<small>${tr('Fictional historical series · Oct 6–19, 2026','Serie histórica ficticia · 6–19 oct 2026')}</small></span><span class="tower-trend-rate">${(total/towerRange).toFixed(1)}<small>${tr('per day','por día')}</small></span></div><svg class="tower-line-chart" viewBox="0 0 600 165" role="img" aria-label="${esc(tr(`Illustrative completions for October ${days[0]}–19: ${values.join(', ')}. Total ${total}.`,`Completados ilustrativos del ${days[0]} al 19 de octubre: ${values.join(', ')}. Total ${total}.`))}"><defs><linearGradient id="tower-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#1d70b7" stop-opacity=".3"/><stop offset="100%" stop-color="#1d70b7" stop-opacity="0"/></linearGradient></defs>${[0,10,20,30].map(v=>{const y=H-v/max*(H-12);return`<line x1="34" x2="594" y1="${y}" y2="${y}" class="tower-chart-grid"/><text x="8" y="${y+3}" class="tower-chart-text">${v}</text>`}).join('')}<path d="${area}" fill="url(#tower-area)"/><path d="${line}" class="tower-chart-line"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3.5" class="tower-chart-point"><title>${days[i]} ${tr('Oct','oct')}: ${values[i]} ${tr('completions','completados')}</title></circle>${(values.length===7||i%2===0||i===values.length-1)?`<text x="${x}" y="156" text-anchor="middle" class="tower-chart-text">${days[i]}</text>`:''}`).join('')}</svg><div class="tower-chart-caption"><span><i></i>${tr('Daily completions · Sample history','Completados diarios · Historial de ejemplo')}</span><span>${tr('Oct 2026','oct 2026')}</span></div>`;
}
function towerStages(){
 const total=state.shipments.length;
 return`<div class="tower-strip-heading"><span>${tr('Current shipment stages','Etapas actuales')}</span><small>${total} ${tr('records','registros')}</small></div><div class="tower-stacked" aria-hidden="true">${Object.keys(statusLabels).map((key,i)=>{const n=state.shipments.filter(s=>s.status===key).length;return n?`<span style="width:${n/total*100}%;--stage-color:var(--tower-stage-${i})"></span>`:''}).join('')}</div><div class="tower-stage-legend">${Object.keys(statusLabels).map((key,i)=>{const n=state.shipments.filter(s=>s.status===key).length;return n?`<button data-tower-stage="${key}"><i style="background:var(--tower-stage-${i})"></i>${tr(...statusLabels[key])}<b>${n}</b></button>`:''}).join('')}</div>`;
}
function towerArrivals(){
 const dates=Array.from({length:7},(_,i)=>`2026-10-${19+i}`),groups=dates.map(date=>state.shipments.filter(s=>s.status!=='delivered'&&s.eta.startsWith(date))),max=Math.max(1,...groups.map(g=>g.length)),total=groups.reduce((n,g)=>n+g.length,0);
 return`<div class="tower-arrival-summary"><strong>${total}</strong><span>${tr('forecast arrivals in the next 7 days','llegadas previstas en los próximos 7 días')}</span></div><div class="tower-arrival-bars">${groups.map((group,i)=>`<button data-tower-date="${dates[i]}" aria-label="${19+i} ${tr('October','octubre')}: ${group.length} ${tr('expected arrivals','llegadas previstas')}"><b>${group.length}</b><span class="tower-bar-track"><i style="height:${group.length/max*100}%"></i></span><span>${19+i}</span></button>`).join('')}</div><footer>${tr('Forecast ETAs from active demo shipments · Select a day to review.','ETA de embarques demo activos · Selecciona un día para revisar.')}</footer>`;
}
function towerOwners(){
 const counts=new Map();state.shipments.filter(s=>s.status!=='delivered').forEach(s=>counts.set(s.owner,(counts.get(s.owner)||0)+1));const owners=[...counts].sort((a,b)=>b[1]-a[1]),max=Math.max(1,...owners.map(x=>x[1]));
 return`<div class="tower-owner-list">${owners.slice(0,4).map(([name,n],i)=>`<button data-tower-owner="${esc(name)}"><span class="tower-owner-avatar">${name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span class="tower-owner-load"><span><b>${esc(name)}</b><strong>${n}</strong></span><i><em style="width:${n/max*100}%;--owner-color:${i===0?'#1d70b7':i===1?'#8bc53f':'#6b9fbd'}"></em></i></span>${icon('chevron')}</button>`).join('')}</div><footer>${tr('Active assignments · Select an owner to inspect their workload.','Asignaciones activas · Selecciona un responsable para revisar su carga.')}</footer>`;
}
function towerFeed(){return Array.from({length:5},(_,i)=>{const index=(towerEventIndex+8-i)%towerExamples.length,[id,ic,en,es,color]=towerExamples[index],s=state.shipments.find(x=>x.id===id);return`<button class="tower-feed-event" data-shipment="${id}"><span class="tower-event-icon ${color}">${icon(ic)}</span><span><b>${tr(en,es)}</b><small>${id} · ${esc(s?.customer||tr('Demo shipment','Embarque demo'))}</small></span><time>${i===0?tr('Now','Ahora'):`${i*3}m`}</time></button>`}).join('')}
function towerShowRecords(records,title,subtitle){openOverlay(`${modalhead(title)}<div class="modalbody"><p class="muted">${subtitle}</p><div class="tower-records">${records.length?records.map(s=>`<button data-shipment="${s.id}"><span><b>${s.id}</b><small>${esc(s.origin)} → ${esc(s.destination)}</small><small>ETA ${esc(s.eta.replace('T',' · '))}</small></span>${statusBadge(s)}${icon('arrow')}</button>`).join(''):`<div class="empty">${tr('No shipments in this group.','No hay embarques en este grupo.')}</div>`}</div></div><div class="modalfoot">${btn(tr('Close','Cerrar'),'data-close')}</div>`,true)}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.towerRange){towerRange=Number(b.dataset.towerRange);document.querySelector('#tower-trend').innerHTML=towerTrend();document.querySelectorAll('[data-tower-range]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.towerRange)===towerRange)));}
 if(b.hasAttribute('data-tower-play')){towerPlayback=!towerPlayback;b.setAttribute('aria-pressed',String(towerPlayback));b.classList.toggle('playing',towerPlayback);b.innerHTML=icon(towerPlayback?'pause':'play');b.setAttribute('aria-label',towerPlayback?tr('Pause demo activity','Pausar actividad demo'):tr('Play demo activity','Reproducir actividad demo'));document.querySelector('#tower-play-status').textContent=towerPlayback?tr('Playing','Reproduciendo'):tr('Paused','Pausado');if(towerPlayback)towerAdvance();}
 if(b.dataset.towerStage)towerShowRecords(state.shipments.filter(s=>s.status===b.dataset.towerStage),tr(...statusLabels[b.dataset.towerStage]),tr('Current demo shipments in this stage.','Embarques demo actuales en esta etapa.'));
 if(b.dataset.towerDate)towerShowRecords(state.shipments.filter(s=>s.status!=='delivered'&&s.eta.startsWith(b.dataset.towerDate)),tr('Expected arrivals','Llegadas previstas'),`${b.dataset.towerDate} · ${tr('Forecasts in destination local time.','Pronósticos en hora local del destino.')}`);
 if(b.dataset.towerOwner)towerShowRecords(state.shipments.filter(s=>s.status!=='delivered'&&s.owner===b.dataset.towerOwner),b.dataset.towerOwner,tr('Active assignments in this workspace.','Asignaciones activas en este espacio.'));
});
function towerAdvance(){const feed=document.querySelector('#tower-feed');if(!feed||document.hidden||view!=='overview'||feed.contains(document.activeElement))return;towerEventIndex=(towerEventIndex+1)%towerExamples.length;feed.innerHTML=towerFeed();}
document.addEventListener('click',e=>{if(e.target.closest('[data-tower-play]'))document.querySelector('.tower-feed-label .dot')?.classList.toggle('green',towerPlayback)});
setInterval(()=>{if(towerPlayback)towerAdvance()},6500);
